local entries = {
  [467142] = { en="Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects.", description="Aumenta fino a $s1 le cure e fino a $s2 i danni inflitti da tutti gli incantesimi ed effetti magici." },
  [8680] = { en="$s1 Nature damage.", description="$s1 danni Natura." },
  [28377] = { en="Casts a bolt of shadow at the target for $s1 Shadow damage.", description="Scaglia un dardo d'ombra contro il bersaglio, infliggendo $s1 danni da ombra." },
  [400640] = { en="Deals $s1 Frost damage to an enemy target. Deals $s2% increased damage to Frozen targets.", description="Infligge $s1 danni da gelo a un nemico. Infligge il $s2% di danni aggiuntivi ai bersagli congelati." },
  [401937] = { en="Heals a friendly target and the caster for $s1. Low threat.", description="Cura un alleato e chi lancia l'incantesimo di $s1. Basso livello di minaccia." },
  [403677] = { en="Transfers $s1 health every second from the target to the caster.  Lasts $d.", description="Trasferisce $s1 salute ogni secondo dal bersaglio a chi lancia l'incantesimo. Dura $d." },
  [412116] = { en="Absorbs $s1 physical damage on a friendly target, draining mana instead.  Drains $s2 mana from the casting Mage per damage absorbed.  Lasts $d.", description="Assorbe $s1 danni fisici su un alleato, consumando mana al suo posto. Consuma $s2 mana del Mago che lancia l'incantesimo per ogni danno assorbito. Dura $d." },
  [1222226] = { en="Teleport player to relative safety.", description="Teletrasporta il giocatore in un luogo relativamente sicuro." },
  [1251919] = { en="Increases Spell Damage by $s1 for $d.", description="Aumenta i danni degli incantesimi di $s1 per $d." },
  [1251942] = { en="Increases Spell Healing by $s1 for $d.", description="Aumenta le cure degli incantesimi di $s1 per $d." },
  [5614] = { en="Causes $s1 Holy damage to an Undead or Demon target.", description="Infligge $s1 danni sacri a un bersaglio Non Morto o Demone." },
  [6089] = { en="Increases your damage with Wands by $s1.", description="Aumenta di $s1 i danni inflitti con le bacchette." },
  [6307] = { en="Increases party members' Stamina by $s1.", description="Aumenta di $s1 la Tempra dei membri del gruppo." },
  [8112] = { en="Increases the target's Spirit by $s1 for $d.", description="Aumenta di $s1 lo Spirito del bersaglio per $d." },
  [8118] = { en="Increases the target's Strength by $s1 for $d.", description="Aumenta di $s1 la Forza del bersaglio per $d." },
  [8647] = { en="Finishing move that exposes the target for $d, reducing armor per combo point:\r\n   1 point  : ${$b*-1} armor\r\n   2 points: ${$b*-2} armor\r\n   3 points: ${$b*-3} armor\r\n   4 points: ${$b*-4} armor\r\n   5 points: ${$b*-5} armor", description="Mossa finale che espone il bersaglio per $d, riducendone l'armatura in base ai punti combo:\n   1 punto: ${$b*-1} armatura\n   2 punti: ${$b*-2} armatura\n   3 punti: ${$b*-3} armatura\n   4 punti: ${$b*-4} armatura\n   5 punti: ${$b*-5} armatura" },
  [13707] = { en="Increases your chance to get a critical strike with Fist Weapons by $s1%.", description="Aumenta del $s1% la probabilità di infliggere un colpo critico con le armi a pugno." },
  [16253] = { en="Increases your chance to block attacks with a shield by $s1% and increases the amount blocked by $s2%.", description="Aumenta del $s1% la probabilità di bloccare gli attacchi con uno scudo e del $s2% la quantità di danni bloccati." },
  [18137] = { en="The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28377s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description="Chi lancia l'incantesimo è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza colpisce chi lancia l'incantesimo, l'attaccante subisce $28377s1 danni da ombra. Gli attaccanti possono subire danni solo una volta ogni pochi secondi. Questi danni non generano minaccia. $n cariche. Dura $d." },
  [18867] = { en="Instantly blasts the target for $s2 Shadow damage.  If the target dies within $d of Shadowburn, and yields experience or honor, the caster gains a Soul Shard.", description="Colpisce istantaneamente il bersaglio, infliggendo $s2 danni da ombra. Se il bersaglio muore entro $d da Consumazione dell'Anima e fornisce esperienza o onore, chi lancia l'incantesimo ottiene un Frammento d'Anima." },
  [20900] = { en="An aimed shot that increases ranged damage by $s1. Aimed Shot shares its cooldown with Multi-Shot.", description="Un tiro mirato che aumenta di $s1 i danni a distanza. Tiro Mirato condivide il tempo di recupero con Tiro Multiplo." },
  [461810] = { en="Blasts nearby enemies with thunder increasing the time between their attacks by $s2% for $d and doing $s1 damage to them.  Will affect up to $i targets.", description="Colpisce i nemici vicini con un tuono, aumentando del $s2% l'intervallo tra i loro attacchi per $d e infliggendo $s1 danni. Può colpire fino a $i bersagli." },
  [436434] = { en="Warlord", description="Signore della Guerra" },
  [1235116] = { en="Take on the guise of a ninja assassin.", description="Assumi le sembianze di un ninja assassino." },
  [408481] = { en="Hurls a lightning bolt at the enemy, dealing $s1 Nature damage and then jumping to additional nearby enemies.  Each jump reduces the damage by 30%.  Affects $x1 total targets.", description="Scaglia un fulmine contro il nemico, infliggendo $s1 danni da natura, poi rimbalza sui nemici vicini. Ogni rimbalzo riduce i danni del 30%. Colpisce $x1 bersagli in totale." },
  [1300942] = { en="Increased Defense +$s1", description="Difesa aumentata di $s1" },
  [1010] = { en="Curse the target with idiocy, reducing Intellect and Spirit by $s1 every $t3 seconds until each is reduced by a total of $*15;s1.  Only one Curse per Warlock can be active on any one target.", description="Maledice il bersaglio con l'idiozia, riducendo Intelletto e Spirito di $s1 ogni $t3 secondi, fino a una riduzione totale di $*15;s1 per ciascuna caratteristica. Ogni Stregone può avere attiva una sola Maledizione per bersaglio." },
  [2832] = { en="Permanently increase the Stamina value by 2 and the armor value by 16 of an item worn on the chest, legs, hands or feet.", description="Aumenta permanentemente di 2 la Tempra e di 16 l'armatura di un oggetto indossato sul torace, sulle gambe, sulle mani o sui piedi." },
  [5403] = { en="Inflicts $s1 Frost damage to nearby enemies, stunning them for $d.", description="Infligge $s1 danni da gelo ai nemici vicini, stordendoli per $d." },
  [5781] = { en="Reduces an enemy's Strength by $s1 and Agility by $s2 for $d.", description="Riduce di $s1 la Forza e di $s2 l'Agilità di un nemico per $d." },
  [6450] = { en="Teaches your tamed pet to be more resistant to magic.  This increases the pet's resistance to all magic schools to 6.", description="Insegna al tuo famiglio addomesticato a resistere meglio alla magia. Aumenta a 6 la resistenza del famiglio a tutte le scuole di magia." },
  [6451] = { en="Teaches your tamed pet to be more resistant to magic.  This increases the pet's resistance to all magic schools to 9.", description="Insegna al tuo famiglio addomesticato a resistere meglio alla magia. Aumenta a 9 la resistenza del famiglio a tutte le scuole di magia." },
  [6507] = { en="Increases the Physical damage dealt by nearby party members by $s1 for $d.", description="Aumenta di $s1 i danni fisici inflitti dai membri del gruppo vicini per $d." },
  [6530] = { en="Tosses dirt into an enemy's eyes, reducing its chance to hit with attacks by $s1% for $d.", description="Getta terra negli occhi di un nemico, riducendo del $s1% la sua probabilità di colpire con gli attacchi per $d." },
  [7020] = { en="Increases the caster's armor by $s1 for $d.", description="Aumenta di $s1 l'armatura di chi lancia l'incantesimo per $d." },
  [8198] = { en="Blasts nearby enemies with thunder increasing, the time between their attacks by $s2% for $d and doing $s1 damage to them. Will affect up to $i targets.", description="Colpisce i nemici vicini con un tuono, aumentando del $s2% l'intervallo tra i loro attacchi per $d e infliggendo $s1 danni. Può colpire fino a $i bersagli." },
  [8955] = { en="Soothes the target beast, reducing the range at which it will attack you by $s1 yards.  Only affects Beast targets level 55 or lower.  Lasts $d.", description="Calma la bestia bersaglio, riducendo di $s1 metri la distanza alla quale ti attacca. Ha effetto solo sulle bestie di livello 55 o inferiore. Dura $d." },
  [9035] = { en="Weakens the target enemy, reducing melee attack power by $s1 and reducing the effectiveness of any healing by $s2%. Lasts $d.", description="Indebolisce il nemico bersaglio, riducendo di $s1 la potenza d'attacco in mischia e del $s2% l'efficacia delle cure. Dura $d." },
  [9578] = { en="Fade out, discouraging enemies from attacking you for $d.  More effective than Fade (rank 1).", description="Svanisci, scoraggiando i nemici dall'attaccarti per $d. Più efficace di Dissolvenza (grado 1)." },
  [9579] = { en="Fade out, discouraging enemies from attacking you for $d.  More effective than Fade (rank 2).", description="Svanisci, scoraggiando i nemici dall'attaccarti per $d. Più efficace di Dissolvenza (grado 2)." },
  [9592] = { en="Fade out, discouraging enemies from attacking you for $d.  More effective than Fade (rank 3).", description="Svanisci, scoraggiando i nemici dall'attaccarti per $d. Più efficace di Dissolvenza (grado 3)." },
  [9823] = { en="Pounce, stunning the target for $d and causing $9824o1 damage over $9824d.  Must be prowling and behind the target.  Awards $s3 combo $lpoint:points;.", description="Balza sul bersaglio, stordendolo per $d e infliggendo $9824o1 danni in $9824d. Richiede furtività e di trovarsi alle spalle del bersaglio. Fornisce $s3 $lpoint:points; combo." },
  [9901] = { en="Soothes the target beast, reducing the range at which it will attack you by $s1 yards.  Only affects Beast targets level 70 or lower.  Lasts $d.", description="Calma la bestia bersaglio, riducendo di $s1 metri la distanza alla quale ti attacca. Ha effetto solo sulle bestie di livello 70 o inferiore. Dura $d." },
  [10368] = { en="Instantly shields the target, absorbing $s1 damage.  Lasts $d.", description="Protegge istantaneamente il bersaglio, assorbendo $s1 danni. Dura $d." },
  [10667] = { en="Increases Strength by $s1 when consumed. Effect lasts for 60 minutes.", description="Aumenta di $s1 la Forza quando viene consumato. L'effetto dura 60 minuti." },
  [10668] = { en="Increases Stamina by $s1 when consumed. Effect lasts for 60 minutes.", description="Aumenta di $s1 la Tempra quando viene consumato. L'effetto dura 60 minuti." },
  [10669] = { en="Increases Agility by $s1 when consumed. Effect lasts for 60 minutes.", description="Aumenta di $s1 l'Agilità quando viene consumato. L'effetto dura 60 minuti." },
  [10692] = { en="Increases Intellect by $s1 when consumed. Effect lasts for 60 minutes.", description="Aumenta di $s1 l'Intelletto quando viene consumato. L'effetto dura 60 minuti." },
  [10693] = { en="Increases Spirit by $s1 when consumed. Effect lasts for 60 minutes.", description="Aumenta di $s1 lo Spirito quando viene consumato. L'effetto dura 60 minuti." },
  [10941] = { en="Fade out, discouraging enemies from attacking you for $d.  More effective than Fade (rank 4).", description="Svanisci, scoraggiando i nemici dall'attaccarti per $d. Più efficace di Dissolvenza (grado 4)." },
  [10942] = { en="Fade out, discouraging enemies from attacking you for $d.  More effective than Fade (rank 5).", description="Svanisci, scoraggiando i nemici dall'attaccarti per $d. Più efficace di Dissolvenza (grado 5)." },
  [11683] = { en="Ignites the area surrounding the caster, causing $s2 Fire damage to $ghimself:herself; and $11681s1 Fire damage to all nearby enemies every $t2 sec.  Lasts $d.", description="Incendia l'area intorno a chi lancia l'incantesimo, infliggendo $s2 danni da fuoco a $ghimself:herself; e $11681s1 danni da fuoco a tutti i nemici vicini ogni $t2 secondi. Dura $d." },
  [11684] = { en="Ignites the area surrounding the caster, causing $s2 Fire damage to $ghimself:herself; and $11682s1 Fire damage to all nearby enemies every $t2 sec.  Lasts $d.", description="Incendia l'area intorno a chi lancia l'incantesimo, infliggendo $s2 danni da fuoco a $ghimself:herself; e $11682s1 danni da fuoco a tutti i nemici vicini ogni $t2 secondi. Dura $d." },
  [11771] = { en="Surrounds the target in a shield of fire. Every strike against the target causes $s1 Fire damage to the attacker. Lasts $d.  Your pet cannot cast Fire Shield on itself.", description="Avvolge il bersaglio in uno scudo di fuoco. Ogni colpo subito infligge $s1 danni da fuoco all'attaccante. Dura $d. Il tuo famiglio non può lanciare Scudo di Fuoco su di sé." },
  [11983] = { en="Inflicts $s3 Nature damage to nearby enemies, reducing their chance to hit with attacks by $s1% for $d.", description="Infligge $s3 danni da natura ai nemici vicini, riducendo del $s1% la loro probabilità di colpire con gli attacchi per $d." },
  [12323] = { en="Causes all nearby enemies to be Dazed, reducing movement speed by $s1% for $d.", description="Stordisce tutti i nemici vicini, riducendone la velocità di movimento del $s1% per $d." },
  [12562] = { en="Inflicts $s1 Fire damage and stuns targets for $d in a 10 yard radius. Any damage will break the effect.", description="Infligge $s1 danni da fuoco e stordisce i bersagli per $d entro un raggio di 10 metri. Qualsiasi danno subito interrompe l'effetto." },
  [12606] = { en="Increases the effect of your Amplify Magic and Dampen Magic spells by $s1%.", description="Aumenta del $s1% l'effetto degli incantesimi Amplificazione della Magia e Attenuazione della Magia." },
  [12627] = { en="A cloud of noxious gas inflicts $12626s1 Nature damage every $t1 sec to players within $12626A1 yards.", description="Una nube di gas nocivo infligge $12626s1 danni da natura ogni $t1 secondi ai giocatori entro $12626A1 metri." },
  [12667] = { en="Drains $s1 health from nearby enemies, healing the caster for up to $e times the amount stolen.", description="Assorbe $s1 salute dai nemici vicini e cura chi lancia l'incantesimo fino a un massimo di $e volte la quantità sottratta." },
  [12686] = { en="Increases Attack Power by $s1 and melee attack speed by $s2% for $d.", description="Aumenta di $s1 la potenza d'attacco e del $s2% la velocità d'attacco in mischia per $d." },
  [12700] = { en="Increases your chance to get a critical strike with Axes and Polearms by $s1%.", description="Aumenta del $s1% la probabilità di infliggere un colpo critico con asce e armi ad asta." },
  [12708] = { en="Gives your Pummel ability a $s1% chance to daze the target.", description="Conferisce a Percossa una probabilità del $s1% di stordire il bersaglio." },
  [12731] = { en="Rend earth and stone, dealing $s1 Physical damage. Deals $s2 times as much damage to Earth Elementals, Golems, and Titan-forged.", description="Squarcia terra e roccia, infliggendo $s1 danni fisici. Infligge danni moltiplicati per $s2 agli elementali della terra, ai golem e ai Forgiati dai Titani." },
  [12733] = { en="Increases all Resistances by $s2 and grants Immunity to Fear for $d.", description="Aumenta di $s2 tutte le resistenze e conferisce immunità alla paura per $d." },
  [12749] = { en="Activates your Mithril Mechanical Dragonling to fight for you for $d.  It requires an hour to cool down before it can be used again.", description="Attiva il tuo Draghetto meccanico in mithril, che combatte al tuo fianco per $d. Richiede un'ora per ricaricarsi prima di poter essere usato di nuovo." },
  [12766] = { en="Creates a cloud of poison in a $a1 yard radius around the caster. Enemies inside the cloud suffer $1300240s1 Nature damage every $1300240t1 sec.  Deals $1300240s2 times as much damage to Trolls.  Lasts for $d.", description="Crea una nube velenosa con raggio di $a1 metri intorno a chi lancia l'incantesimo. I nemici al suo interno subiscono $1300240s1 danni da natura ogni $1300240t1 secondi. Infligge danni moltiplicati per $1300240s2 ai Troll. Dura $d." },
  [12792] = { en="Increases all threat generated in Defensive stance by an additional $s1% while a shield is equipped.", description="Aumenta di un ulteriore $s1% tutta la minaccia generata in Assetto Difensivo quando è equipaggiato uno scudo." },
  [12797] = { en="Increases damage dealt by your Revenge ability by $m1%.", description="Aumenta del $m1% i danni inflitti da Vendetta." },
  [12834] = { en="Your critical strikes cause your opponent to Bleed, dealing $m1% of your melee weapon's average damage over $412609d.", description="I colpi critici fanno Sanguinare l'avversario, infliggendo danni pari al $m1% dei danni medi dell'arma da mischia in $412609d." },
  [12862] = { en="Reduces the global cooldown and cast time of your Slam ability by ${$m1/-1000}.2 sec. In addition, Slam no longer interrupts or delays your melee swing and Slam's cooldown is reduced by ${$m3/-1000}.1 sec.", description="Riduce di ${$m1/-1000}.2 s il tempo di recupero globale e il tempo di lancio di Schianto. Inoltre, Schianto non interrompe né ritarda più il colpo dell'arma da mischia e il suo tempo di recupero si riduce di ${$m3/-1000}.1 s." },
  [12946] = { en="Reduces nearby enemies' Strength by $s2 and Agility by $s3 for $d., as well as preventing them from casting spells.", description="Riduce la Forza dei nemici vicini di $s2 e l'Agilità di $s3 per $d., impedendo inoltre loro di lanciare incantesimi." },
  [12956] = { en="Increases Defense by $s1, Shadow resistance by $s2 and your normal health regeneration by 3.", description="Aumenta di $s1 la Difesa, di $s2 la resistenza all'ombra e di 3 la normale rigenerazione della salute." },
  [12962] = { en="Reduces the duration of Stun and Fear effects inflicted on you by $s1%.", description="Riduce del $s1% la durata degli effetti di stordimento e paura subiti." },
  [12975] = { en="When activated, this ability temporarily grants you $12976s1% of your maximum health for $12976d. After the effect expires, the health is lost.", description="Quando attivata, questa abilità conferisce temporaneamente $12976s1% della tua salute massima per $12976d. Al termine dell'effetto, la salute aggiuntiva viene persa." },
  [13006] = { en="Shrinks the target reducing their attack power by $13003s1.  Thats what it usually does anyway.....", description="Rimpicciolisce il bersaglio e ne riduce la potenza d'attacco di $13003s1. Almeno, di solito è questo che fa....." },
  [13163] = { en="The hunter takes on the aspects of a monkey, increasing chance to dodge by $s1%.  Only one Aspect can be active at a time.", description="Il cacciatore assume l'aspetto della scimmia, aumentando del $s1% la probabilità di schivata. È possibile avere un solo Aspetto attivo alla volta." },
  [13180] = { en="Engage in mental combat with a humanoid target to try and control their mind.  If all works well, you will control the mind of the target for $13181d .....", description="Ingaggia un duello mentale con un bersaglio umanoide nel tentativo di controllarne la mente. Se tutto va bene, controllerai la mente del bersaglio per $13181d ....." },
  [13183] = { en="Deals $13184s1 Fire damage for $d to all targets in a cone in front of the Engineer. Deals $s2 times as much damage to Beasts.  That is unless it explodes.....", description="Infligge $13184s1 danni da fuoco per $d a tutti i bersagli in un cono davanti all'Ingegnere. Infligge danni moltiplicati per $s2 alle bestie. A meno che non esploda....." },
  [13184] = { en="Deals $s1 Fire damage every $13183t1 sec.", description="Infligge $s1 danni da fuoco ogni $13183t1 secondi." },
  [13219] = { en="Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, reducing all healing effects used on them by $13218s1 for $13218d.  Stacks up to $13218u times on a single target.  $m2 charges.", description="Ricopre un'arma di veleno, che dura ${$m1/60} minuti.\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13218s1 per $13218d. Si accumula fino a $13218u volte sullo stesso bersaglio. $m2 cariche." },
  [13220] = { en="Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $13219h% chance of poisoning the enemy, reducing all healing effects used on them by $13218s1 for $13218d.  Stacks up to $13218u times on a single target.  $m3 charges.", description="Ricopre un'arma di veleno, che dura ${$m2/60} minuti.\nOgni colpo ha una probabilità del $13219h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13218s1 per $13218d. Si accumula fino a $13218u volte sullo stesso bersaglio. $m3 cariche." },
  [13225] = { en="Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, reducing all healing effects used on them by $13222s1 for $13222d.  Stacks up to $13222u times on a single target.  $m2 charges.", description="Ricopre un'arma di veleno, che dura ${$m1/60} minuti.\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13222s1 per $13222d. Si accumula fino a $13222u volte sullo stesso bersaglio. $m2 cariche." },
  [13226] = { en="Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, reducing all healing effects used on them by $13223s1 for $13223d.  Stacks up to $13223u times on a single target.  $m2 charges.", description="Ricopre un'arma di veleno, che dura ${$m1/60} minuti.\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13223s1 per $13223d. Si accumula fino a $13223u volte sullo stesso bersaglio. $m2 cariche." },
  [13227] = { en="Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, reducing all healing effects used on them by $13224s1 for $13224d.  Stacks up to $13224u times on a single target.  $m2 charges.", description="Ricopre un'arma di veleno, che dura ${$m1/60} minuti.\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13224s1 per $13224d. Si accumula fino a $13224u volte sullo stesso bersaglio. $m2 cariche." },
  [13228] = { en="Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $13225h% chance of poisoning the enemy, reducing all healing effects used on them by $13222s1 for $13222d.  Stacks up to $13222u times on a single target.  $m3 charges.", description="Ricopre un'arma di veleno, che dura ${$m2/60} minuti.\nOgni colpo ha una probabilità del $13225h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13222s1 per $13222d. Si accumula fino a $13222u volte sullo stesso bersaglio. $m3 cariche." },
  [13229] = { en="Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $13226h% chance of poisoning the enemy, reducing all healing effects used on them by $13223s1 for $13223d.  Stacks up to $13223u times on a single target.  $m3 charges.", description="Ricopre un'arma di veleno, che dura ${$m2/60} minuti.\nOgni colpo ha una probabilità del $13226h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13223s1 per $13223d. Si accumula fino a $13223u volte sullo stesso bersaglio. $m3 cariche." },
  [13230] = { en="Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $13227h% chance of poisoning the enemy, reducing all healing effects used on them by $13224s1 for $13224d.  Stacks up to $13224u times on a single target.  $m3 charges.", description="Ricopre un'arma di veleno, che dura ${$m2/60} minuti.\nOgni colpo ha una probabilità del $13227h% di avvelenare il nemico, riducendo tutte le cure ricevute di $13224s1 per $13224d. Si accumula fino a $13224u volte sullo stesso bersaglio. $m3 cariche." },
  [13261] = { en="Malfunction. Deals $s1 Fire damage.", description="Malfunzionamento. Infligge $s1 danni da fuoco." },
  [13278] = { en="The devices charges over time using your life force and then directs a burst of energy at your opponent. Deals $s2 times as much damage to Gnomes.", description="Il dispositivo si carica gradualmente usando la tua forza vitale, poi sprigiona un'esplosione di energia contro l'avversario. Infligge danni moltiplicati per $s2 agli Gnomi." },
  [13338] = { en="Forces an enemy to speak in Demonic, reducing its casting speed by $s1% for $d. Only one curse per warlock can be active on any one target.", description="Costringe un nemico a parlare in Demoniaco, riducendone la velocità di lancio del $s1% per $d. Ogni Stregone può avere attiva una sola maledizione per bersaglio." },
  [13491] = { en="Pummel the target for $s1 damage and interrupt the spell being cast for $d.", description="Colpisce il bersaglio con $s1 danni e interrompe l'incantesimo che sta lanciando per $d." },
  [13524] = { en="Lowers the Attack Power of the target by $s1 for $d.", description="Riduce di $s1 la potenza d'attacco del bersaglio per $d." },
  [13526] = { en="Corrosive acid that deals $m1 Nature damage every $t sec and lowers target's armor by $m2 for $d.", description="Acido corrosivo che infligge $m1 danni da natura ogni $t secondi e riduce di $m2 l'armatura del bersaglio per $d." },
  [13589] = { en="Increases the attack speed of all nearby party members by $s1%. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.", description="Aumenta del $s1% la velocità d'attacco di tutti i membri del gruppo vicini. Ogni paladino può applicare una sola aura alla volta a ciascun giocatore. L'aura dura finché non viene annullata." },
  [13692] = { en="Reduces an enemy's Strength by $s1 and its Agility by $s2 for $d.", description="Riduce di $s1 la Forza e di $s2 l'Agilità di un nemico per $d." },
  [13709] = { en="Your attacks with Maces ignore up to $m1% of your target's armor.", description="Gli attacchi con le mazze ignorano fino al $m1% dell'armatura del bersaglio." },
  [13712] = { en="Increases your Dodge chance by $s1%.", description="Aumenta del $s1% la probabilità di schivata." },
  [13715] = { en="Increases the damage done by your off-hand weapon by $s1%.", description="Aumenta del $s1% i danni inflitti dall'arma nella mano secondaria." },
  [13732] = { en="Reduces the Energy cost of your Sinister Strike ability by $s1.", description="Riduce di $s1 il costo in energia di Colpo Funesto." },
  [13742] = { en="Reduces the cooldown of your Sprint and Evasion abilities by $m1%.", description="Riduce del $m1% il tempo di recupero di Sprint e Elusione." },
  [13743] = { en="Gives a $m1% chance to remove all movement impairing effects when you activate your Sprint ability.", description="Conferisce una probabilità del $m1% di rimuovere tutti gli effetti che limitano il movimento quando attivi Sprint." },
  [13744] = { en="Increases Fire resistance by $s2 and absorbs $s1 Fire damage.  Lasts $d.", description="Aumenta di $s2 la resistenza al fuoco e assorbe $s1 danni da fuoco. Dura $d." },
  [13750] = { en="Increases your Energy regeneration rate by $s1% for $d.", description="Aumenta del $s1% la velocità di rigenerazione dell'energia per $d." },
  [13754] = { en="Gives your Kick ability a $m1% chance to Silence the target for $18425d.", description="Conferisce a Calcio una probabilità del $m1% di silenziare il bersaglio per $18425d." },
  [13795] = { en="Place a Fire trap that will burn the first enemy to approach for $13797o1 Fire damage over $13797d. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che brucia il primo nemico che si avvicina, infliggendo $13797o1 danni da fuoco in $13797d. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [13808] = { en="Inflicts $s1 Fire damage and stuns targets in a 10 yard radius for $d.  Any damage will break the effect.", description="Infligge $s1 danni da fuoco e stordisce i bersagli entro un raggio di 10 metri per $d. Qualsiasi danno subito interrompe l'effetto." },
  [13809] = { en="Place a Frost trap that creates an ice slick around itself for $13810d when the first enemy approaches it. All enemies within $13810a1 yards will be slowed by $14207s1% while in the area of effect. Trap will exist for $d. Only one Frost trap can be active at a time.", description="Piazza una trappola di gelo che crea una lastra di ghiaccio intorno a sé per $13810d quando il primo nemico vi si avvicina. Tutti i nemici entro $13810a1 metri sono rallentati del $14207s1% mentre si trovano nell'area. La trappola resta attiva per $d. È possibile avere una sola trappola di gelo attiva alla volta." },
  [13813] = { en="Place a Fire trap that explodes when an enemy approaches, causing $13812s1 Fire damage and $13812o2 additional Fire damage over $13812d to all within $13812a1 yards. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che esplode quando un nemico si avvicina, infliggendo $13812s1 danni da fuoco e altri $13812o2 danni da fuoco in $13812d a tutti i nemici entro $13812a1 metri. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [13877] = { en="Increases your melee attack speed by $s1% and your melee attacks strike an additional nearby opponent. Lasts $d.", description="Aumenta del $s1% la velocità d'attacco in mischia e i tuoi attacchi in mischia colpiscono un ulteriore nemico vicino. Dura $d." },
  [13896] = { en="The priest becomes surrounded with anti-magic energy.  Any successful spell cast against the priest will burn $6347s1 of the attacker's Mana, causing 1 Shadow damage for each point of Mana burned.  Lasts $d.", description="Il sacerdote viene avvolto da energia antimagia. Ogni incantesimo lanciato con successo contro il sacerdote consuma $6347s1 mana dell'attaccante, infliggendo 1 danno da ombra per ogni punto di mana consumato. Dura $d." },
  [13958] = { en="Reduces the chance enemies have to detect you while in Stealth mode as if you were ${$m1/5} $llevel:levels; higher.", description="Riduce la probabilità che i nemici ti individuino in modalità furtiva, come se fossi ${$m1/5} livelli $llevel:levels;." },
  [13960] = { en="Gives your melee weapon attacks a benefit depending on the weapon.\r\n\r\n    |CFFFFFFFFAxe/Sword:|R Your successful\r\n    melee attacks have a $s3% chance\r\n    to trigger an extra attack on the \r\n    target.\r\n\r\n    |CFFFFFFFFDagger/Fist:|R Increases your\r\n    critical strike chance by $s1%.\r\n\r\n    |CFFFFFFFFMace:|R Your attacks ignore $s2% of\r\n    your target's armor.", description="Le armi da mischia conferiscono un beneficio in base al tipo.\n\n    |CFFFFFFFFAscia/Spada:|R I tuoi attacchi in mischia andati a segno hanno una probabilità del $s3% di sferrare un attacco aggiuntivo al bersaglio.\n\n    |CFFFFFFFFPugnale/Arma a pugno:|R Aumenta del $s1% la probabilità di colpo critico.\n\n    |CFFFFFFFFMazza:|R I tuoi attacchi ignorano il $s2% dell'armatura del bersaglio." },
  [13983] = { en="Gives you a $m1% chance to add a Combo Point to your target after Dodging an attack or fully resisting a spell.", description="Conferisce una probabilità del $m1% di aggiungere un punto combo al bersaglio dopo aver schivato un attacco o aver resistito completamente a un incantesimo." },
  [14057] = { en="Increases the damage dealt by your Backstab, Garrote, Ambush, and Mutilate abilities by $s1%.", description="Aumenta del $s1% i danni inflitti da Attacco alle Spalle, Garrota, Agguato e Mutilazione." },
  [14079] = { en="Increases the critical strike chance of your Ambush ability by $s1%.", description="Aumenta del $s1% la probabilità di colpo critico di Agguato." },
  [14082] = { en="Reduces the Energy cost of your Cheap Shot and Garrote abilities by $m1, and your Garrote ability no longer requires you to be behind your target.", description="Riduce di $m1 il costo in energia di Colpo Basso e Garrota, e Garrota non richiede più di trovarsi alle spalle del bersaglio." },
  [14084] = { en="Increases the radius of your Distract ability by $s1 yds, and further reduces the Stealth detection of distracted enemies as though they were an additional ${$m2/-5} $Llevel:levels; lower.", description="Aumenta di $s1 m il raggio di Distrazione e riduce ulteriormente la capacità dei nemici distratti di individuarti in furtività, come se fossero ${$m2/-5} livelli $Llevel:levels;." },
  [14110] = { en="Poisons an enemy for $d. and drains its mana every $t2 sec., transferring it to the caster.", description="Avvelena un nemico per $d e ne prosciuga il mana ogni $t2 secondi, trasferendolo a chi lancia l'incantesimo." },
  [14113] = { en="Increases the chance to apply Poisons to your target by $m1%, and gives Poison applications a $m2% chance to not consume a charge.", description="Aumenta del $m1% la probabilità di applicare veleni al bersaglio e conferisce ai veleni una probabilità del $m2% di non consumare una carica." },
  [14118] = { en="Wounds the target causing them to bleed for $o1 damage over $d. Deals $s2 times as much damage to Dragonkin.", description="Ferisce il bersaglio, facendolo sanguinare per $o1 danni in $d. Infligge danni moltiplicati per $s2 ai Draghi." },
  [14128] = { en="Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by $s1%.", description="Aumenta del $s1% il bonus ai danni da colpo critico di Colpo Funesto, Attacco alle Spalle, Agguato, Mutilazione, Colpo Spettrale e Emorragia." },
  [14144] = { en="After killing a non-trivial enemy, gives you a $m1% increased critical strike chance on your next Sinister Strike, Backstab, Ambush, Mutilate, or Ghostly Strike. Lasts $14143d.", description="Dopo aver ucciso un nemico impegnativo, aumenta del $m1% la probabilità di colpo critico del tuo prossimo Colpo Funesto, Attacco alle Spalle, Agguato, Mutilazione o Colpo Spettrale. Dura $14143d." },
  [14156] = { en="Gives your finishing moves a $m1% chance to add a Combo Point to your target.", description="Conferisce alle mosse finali una probabilità del $m1% di aggiungere un punto combo al bersaglio." },
  [14158] = { en="Increases all damage dealt by $m1% against Humanoid and Giant targets.", description="Aumenta del $m1% tutti i danni inflitti ai bersagli Umanoidi e Giganti." },
  [14162] = { en="Increases the damage done by your Eviscerate ability by $m1%.", description="Aumenta del $m1% i danni inflitti da Eviscerazione." },
  [14168] = { en="Reduces the Energy cost of your Expose Armor ability by $m1, and refunds $m2 Combo $LPoint:Points; when cast with $m3 Combo Points.", description="Riduce di $m1 il costo in energia di Scopri Armatura e restituisce $m2 punti $LPoint:Points; quando viene usata con $m3 punti combo." },
  [14171] = { en="Causes your attacks to ignore $m1% of your target's Armor and increases the damage dealt by your Rupture ability by $m2%.", description="Fa sì che i tuoi attacchi ignorino il $m1% dell'armatura del bersaglio e aumenta del $m2% i danni inflitti da Rottura." },
  [14174] = { en="Enemies Stunned by your Kidney Shot ability take $s1% increased damage from your poisons and attacks.", description="I nemici storditi da Colpo Basso subiscono il $s1% di danni aggiuntivi dai tuoi veleni e attacchi." },
  [14177] = { en="When activated, increases the critical strike chance of your next Sinister Strike, Backstab, Ambush, Eviscerate, or Mutilate by $s1%.", description="Quando attivata, aumenta del $s1% la probabilità di colpo critico del tuo prossimo Colpo Funesto, Attacco alle Spalle, Agguato, Eviscerazione o Mutilazione." },
  [14179] = { en="Your finishing moves have a $m1% chance per Combo Point to restore $14181s1 Energy.", description="Le tue mosse finali hanno una probabilità del $m1% per punto combo di ripristinare $14181s1 energia." },
  [14183] = { en="Adds $s1 Combo Points to your target. You must add to or use those combo points within $d or the combo points are lost.", description="Aggiunge $s1 punti combo al bersaglio. Devi aggiungere altri punti combo o usarli entro $d, altrimenti andranno persi." },
  [14186] = { en="Your critical strikes from abilities that add Combo Points have a $m1% chance to add an additional Combo Point.", description="I colpi critici delle abilità che aggiungono punti combo hanno una probabilità del $m1% di aggiungerne uno ulteriore." },
  [14253] = { en="Attempts to cure $s2 poison $leffect:effects; on the target, and $3137s1 more poison $leffect:effects; every $t1 seconds for $d.", description="Tenta di curare $s2 $leffect:effects; da veleno sul bersaglio e altri $3137s1 $leffect:effects; da veleno ogni $t1 secondi per $d." },
  [14278] = { en="A strike that deals $s1% ($m4% if a Dagger is equipped in your Main Hand) weapon damage and increases your chance to dodge by $s2% for $d.  Awards $s3 combo $lpoint:points;.", description="Un attacco che infligge danni pari al $s1% dell'arma ($m4% se hai un pugnale nella mano principale) e aumenta del $s2% la probabilità di schivata per $d. Fornisce $s3 $lpoint:points; combo." },
  [14294] = { en="Continuously fires a volley of ammo at the target area, causing $1279719s1 Arcane damage to enemy targets within $a1 yards every $t3 sec for $d.", description="Scaglia continuamente una raffica di munizioni nell'area bersaglio, infliggendo $1279719s1 danni arcani ai nemici entro $a1 metri ogni $t3 secondi per $d." },
  [14295] = { en="Continuously fires a volley of ammo at the target area, causing $1279715s1 Arcane damage to enemy targets within $a1 yards every $t3 sec for $d.", description="Scaglia continuamente una raffica di munizioni nell'area bersaglio, infliggendo $1279715s1 danni arcani ai nemici entro $a1 metri ogni $t3 secondi per $d." },
  [14302] = { en="Place a Fire trap that will burn the first enemy to approach for $14298o1 Fire damage over $14298d. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che brucia il primo nemico che si avvicina, infliggendo $14298o1 danni da fuoco in $14298d. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [14303] = { en="Place a Fire trap that will burn the first enemy to approach for $14299o1 Fire damage over $14299d. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che brucia il primo nemico che si avvicina, infliggendo $14299o1 danni da fuoco in $14299d. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [14304] = { en="Place a Fire trap that will burn the first enemy to approach for $14300o1 Fire damage over $14300d. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che brucia il primo nemico che si avvicina, infliggendo $14300o1 danni da fuoco in $14300d. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [14305] = { en="Place a Fire trap that will burn the first enemy to approach for $14301o1 Fire damage over $14301d. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che brucia il primo nemico che si avvicina, infliggendo $14301o1 danni da fuoco in $14301d. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [14310] = { en="Place a Frost trap that freezes the first enemy that approaches, preventing all action for up to $14308d. Any damage caused will break the ice. Trap will exist for $d. Only one Frost trap can be active at a time.", description="Piazza una trappola di gelo che congela il primo nemico che vi si avvicina, impedendogli qualsiasi azione per un massimo di $14308d. Qualsiasi danno inflitto rompe il ghiaccio. La trappola resta attiva per $d. È possibile avere una sola trappola di gelo attiva alla volta." },
  [14311] = { en="Place a Frost trap that freezes the first enemy that approaches, preventing all action for up to $14309d. Any damage caused will break the ice. Trap will exist for $d. Only one Frost trap can be active at a time.", description="Piazza una trappola di gelo che congela il primo nemico che vi si avvicina, impedendogli qualsiasi azione per un massimo di $14309d. Qualsiasi danno inflitto rompe il ghiaccio. La trappola resta attiva per $d. È possibile avere una sola trappola di gelo attiva alla volta." },
  [14316] = { en="Place a Fire trap that explodes when an enemy approaches, causing $14314s1 Fire damage and $14314o2 additional Fire damage over $14314d to all within $14314a1 yards. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che esplode quando un nemico si avvicina, infliggendo $14314s1 danni da fuoco e altri $14314o2 danni da fuoco in $14314d a tutti i nemici entro $14314a1 metri. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [14317] = { en="Place a Fire trap that explodes when an enemy approaches, causing $14315s1 Fire damage and $14315o2 additional Fire damage over $14315d to all within $14315a1 yards. Trap will exist for $d. Only one Fire trap can be active at a time.", description="Piazza una trappola di fuoco che esplode quando un nemico si avvicina, infliggendo $14315s1 danni da fuoco e altri $14315o2 danni da fuoco in $14315d a tutti i nemici entro $14315a1 metri. La trappola resta attiva per $d. È possibile avere una sola trappola di fuoco attiva alla volta." },
  [14520] = { en="Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by $s1%.", description="Riduce del $s1% il costo in mana di Punizione, Fuoco Sacro e degli incantesimi istantanei." },
  [14522] = { en="Reduces the duration of Stun, Fear, and Silence effects inflicted on you by $m1%.", description="Riduce del $m1% la durata degli effetti di stordimento, paura e silenziamento subiti." },
  [14523] = { en="Reduces the threat generated by your Holy spells by $s1% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by $m2%.\r\n", description="Riduce del $s1% la minaccia generata dagli incantesimi sacri e del $m2% la durata degli effetti di stordimento, paura e silenziamento subiti." },
  [14531] = { en="Gives you a $m1% chance to gain Focused Casting for $27828d after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by $27828s2%.", description="Conferisce una probabilità del $m1% di ottenere Concentrazione del Lancio per $27828d dopo aver subito un colpo critico in mischia o a distanza. Concentrazione del Lancio impedisce di perdere tempo di lancio quando si subiscono danni e aumenta del $27828s2% la resistenza agli effetti di interruzione." },
  [14744] = { en="Increases the damage dealt by the caster by $s1 for $d.", description="Aumenta di $s1 i danni inflitti da chi lancia l'incantesimo per $d." },
  [14747] = { en="Increases the Armor bonus of your Inner Fire spell by $s1% and increases its total charges by $m2.", description="Aumenta del $s1% il bonus all'armatura di Fuoco Interiore e di $m2 le sue cariche totali." },
  [14750] = { en="Reduces the casting time of your Mana Burn spell by ${$m1/-1000}.1 sec.", description="Riduce di ${$m1/-1000}.1 s il tempo di lancio di Bruciatura del Mana." },
  [14751] = { en="When activated, reduces the Mana cost of your next spell by $s1% and increases its critical effect chance by $s2% if it is capable of a critical effect.", description="Quando attivata, riduce del $s1% il costo in mana del tuo prossimo incantesimo e, se può infliggere un colpo critico, ne aumenta del $s2% la probabilità." },
  [14847] = { en="Permanently enchant a melee weapon to do 8 additional points of fire damage.", description="Incanta permanentemente un'arma da mischia, facendole infliggere 8 danni da fuoco aggiuntivi." },
  [14892] = { en="Your non-periodic critical heals increase your target's Armor by $m1% for $14893d.", description="Le cure critiche non periodiche aumentano del $m1% l'armatura del bersaglio per $14893d." },
  [14898] = { en="Increases the amount healed by your spells by $s1%.", description="Aumenta del $s1% le cure fornite dai tuoi incantesimi." },
  [14901] = { en="Increases your spell healing by up to $s2% of your total Spirit and your spell damage by up to $s1% of your total Spirit.", description="Aumenta le cure dei tuoi incantesimi fino al $s2% del tuo Spirito totale e i danni degli incantesimi fino al $s1% del tuo Spirito totale." },
  [14902] = { en="Stuns an enemy for $d. Must be stealthed. Awards $s2 combo $lpoint:points;.", description="Stordisce un nemico per $d. Richiede furtività. Fornisce $s2 $lpoint:points; combo." },
  [14909] = { en="Increases your Holy damage done by $m1%, and gives a $m2% chance each time your Holy Fire spell deals periodic damage for your next Holy Nova to cost no Mana.", description="Aumenta del $m1% i danni sacri inflitti e conferisce una probabilità del $m2% che, ogni volta che Fuoco Sacro infligge danni periodici, la tua prossima Nova Sacra non costi mana." },
  [14912] = { en="Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by $s1%.", description="Riduce del $s1% il costo in mana di Cura Inferiore, Cura, Cura Maggiore, Penitenza e Preghiera di Cura." },
  [14913] = { en="Gives you a $s1% chance to avoid interruption caused by damage while casting any spell.", description="Conferisce una probabilità del $s1% di evitare interruzioni causate dai danni mentre lanci un incantesimo." },
  [15057] = { en="Restores $s1 health to a friendly mechanical target", description="Ripristina $s1 salute a un bersaglio meccanico alleato." },
  [15058] = { en="Increases the damage done by your spells by $m1% and your critical strike chance by $m2%.", description="Aumenta del $m1% i danni inflitti dai tuoi incantesimi e del $m2% la probabilità di colpo critico." },
  [15107] = { en="Summons a Windwall Totem with $s1 health at the feet of the caster.  The totem protects party members within $15108a1 yards, reducing ranged damage taken by $15108s1.  Lasts $d.", description="Evoca un Totem del Muro del Vento con $s1 salute ai piedi di chi lancia l'incantesimo. Il totem protegge i membri del gruppo entro $15108a1 metri, riducendo i danni a distanza subiti di $15108s1. Dura $d." },
  [15111] = { en="Summons a Windwall Totem with $s1 health at the feet of the caster.  The totem protects party members within $15109a1 yards, reducing ranged damage taken by $15109s1.  Lasts $d.", description="Evoca un Totem del Muro del Vento con $s1 salute ai piedi di chi lancia l'incantesimo. Il totem protegge i membri del gruppo entro $15109a1 metri, riducendo i danni a distanza subiti di $15109s1. Dura $d." },
  [15112] = { en="Summons a Windwall Totem with $s1 health at the feet of the caster.  The totem protects party members within $15110a1 yards, reducing ranged damage taken by $15110s1.  Lasts $d.", description="Evoca un Totem del Muro del Vento con $s1 salute ai piedi di chi lancia l'incantesimo. Il totem protegge i membri del gruppo entro $15110a1 metri, riducendo i danni a distanza subiti di $15110s1. Dura $d." },
  [15237] = { en="Causes an explosion of holy light around the caster, causing $s1 Holy damage to all enemy targets within $a1 yards and healing all party members within $23455a1 yards for $23455s1. These effects cause no threat.", description="Provoca un'esplosione di luce sacra intorno a chi lancia l'incantesimo, infliggendo $s1 danni sacri a tutti i nemici entro $a1 metri e curando tutti i membri del gruppo entro $23455a1 metri di $23455s1. Questi effetti non generano minaccia." },
  [15257] = { en="Your Shadow damage spells have a $s1% chance to increase the Shadow damage you deal by $15258s1% for $15258d, stacking up to $15258u times.", description="Gli incantesimi che infliggono danni da ombra hanno una probabilità del $s1% di aumentare del $15258s1% i danni da ombra inflitti per $15258d. L'effetto si accumula fino a $15258u volte." },
  [15259] = { en="Increases your Shadow damage done by $s1%.", description="Aumenta del $s1% i danni da ombra inflitti." },
  [15260] = { en="Improves your chance to hit with Shadow spells by $s1%.", description="Aumenta del $s1% la probabilità di colpire con incantesimi d'ombra." },
  [15270] = { en="Gives you a $m1% chance to gain a $15271s1% bonus to your Spirit for $15271d after killing a non-trivial target. For the duration, your Mana will regenerate at a $15271s2% of normal rate while casting.", description="Conferisce una probabilità del $m1% di ottenere un bonus del $15271s1% allo Spirito per $15271d dopo aver ucciso un bersaglio impegnativo. Per la durata dell'effetto, il mana si rigenera al $15271s2% della velocità normale durante il lancio." },
  [15275] = { en="Increases the duration of your Shadow Word: Pain spell by ${$s1/1000} sec.", description="Aumenta di ${$s1/1000} secondi la durata di Parola d'Ombra: Dolore." },
  [15286] = { en="Afflicts your target with Shadow energy that causes all party members to be healed for $s1% of any Shadow spell damage you deal for $d. Vampiric Embrace also grants a chance for your Spirit Tap talent to trigger when enemies afflicted by it die.", description="Affligge il bersaglio con energia d'ombra, facendo sì che tutti i membri del gruppo vengano curati di una quantità pari al $s1% dei danni da ombra che infliggi per $d. Abbraccio Vampirico offre anche la possibilità di attivare il talento Tocco Vampirico alla morte dei nemici afflitti." },
  [15318] = { en="Reduces the threat generated by your Shadow spells by $s1%.", description="Riduce del $s1% la minaccia generata dai tuoi incantesimi d'ombra." },
  [15326] = { en="Gives your Shadow damage spells a $m1% chance to stun the target for $15269d.", description="Conferisce agli incantesimi che infliggono danni da ombra una probabilità del $m1% di stordire il bersaglio per $15269d." },
  [15430] = { en="Causes an explosion of holy light around the caster, causing $s1 Holy damage to all enemy targets within $a1 yards and healing all party members within $23458a1 yards for $23458s1. These effects cause no threat.\r\n\r\nEach time Holy Fire deals damage, you have a 5% chance for your next Holy Nova to cost no Mana.\r\n", description="Provoca un'esplosione di luce sacra intorno a chi lancia l'incantesimo, infliggendo $s1 danni sacri a tutti i nemici entro $a1 metri e curando tutti i membri del gruppo entro $23458a1 metri di $23458s1. Questi effetti non generano minaccia.\n\nOgni volta che Fuoco Sacro infligge danni, hai una probabilità del 5% che la tua prossima Nova Sacra non costi mana." },
  [15431] = { en="Causes an explosion of holy light around the caster, causing $s1 Holy damage to all enemy targets within $a1 yards and healing all party members within $23459a1 yards for $23459s1. These effects cause no threat.\r\n\r\nEach time Holy Fire deals damage, you have a 5% chance for your next Holy Nova to cost no Mana.\r\n", description="Provoca un'esplosione di luce sacra intorno a chi lancia l'incantesimo, infliggendo $s1 danni sacri a tutti i nemici entro $a1 metri e curando tutti i membri del gruppo entro $23459a1 metri di $23459s1. Questi effetti non generano minaccia.\n\nOgni volta che Fuoco Sacro infligge danni, hai una probabilità del 5% che la tua prossima Nova Sacra non costi mana." },
  [15473] = { en="Assume Shadowform, increasing your Shadow damage by $s2%, reducing the Mana cost of all Shadow spells by $m4%, increasing the critical strike damage bonus of your Shadow spells by $m5%, and reducing Physical damage taken by you by $s3%. However, you may not cast healing spells while in this form.", description="Assumi la Forma d'Ombra: i danni da ombra aumentano del $s2%, il costo in mana di tutti gli incantesimi d'ombra si riduce del $m4%, il bonus ai danni da colpo critico degli incantesimi d'ombra aumenta del $m5% e i danni fisici subiti si riducono del $s3%. In questa forma non puoi lanciare incantesimi di cura." },
  [15475] = { en="Inflicts $s2 Nature damage and an additional $s1 damage every $t1 sec. to nearby enemies for $d.", description="Infligge $s2 danni da natura e altri $s1 danni ai nemici vicini ogni $t1 secondi per $d." },
  [15487] = { en="Silences the target, preventing them from casting spells for $d and interrupting their spellcasts for $1241057d.", description="Silenzia il bersaglio, impedendogli di lanciare incantesimi per $d e interrompendo il lancio in corso per $1241057d." },
  [15494] = { en="Grants $s1 extra attacks on your next swing. Attacks against Orcs are $1301046s2 times as likely to activate this effect.", description="Conferisce $s1 attacchi aggiuntivi al tuo prossimo colpo. Gli attacchi contro gli Orchi hanno una probabilità $1301046s2 volte superiore di attivare l'effetto." },
  [15594] = { en="When struck in combat has a chance to reduce all damage taken by $15595s1 for $15595d.", description="Quando subisci un colpo in combattimento, hai una probabilità di ridurre tutti i danni subiti di $15595s1 per $15595d." },
  [15595] = { en="Damage taken reduced by $s1.", description="Danni subiti ridotti di $s1." },
  [15600] = { en="${$h/3}% chance on Melee hit to gain $s1 extra attack. Attacks against Dwarves are $s2 times as likely to activate this effect.", description="Probabilità del ${$h/3}% per ogni colpo in mischia di ottenere $s1 attacchi aggiuntivi. Gli attacchi contro i Nani hanno una probabilità $s2 volte superiore di attivare l'effetto." },
  [15604] = { en="Restores $s1 Mana every $t1 sec for $d. This effect is doubled in Mountainous areas.", description="Ripristina $s1 mana ogni $t1 secondi per $d. Questo effetto raddoppia nelle zone montuose." },
  [15646] = { en="Reduces the Mana cost of all spells by $s1 for $d.", description="Riduce di $s1 il costo in mana di tutti gli incantesimi per $d." },
  [15712] = { en="Flings a magical boomerang towards target enemy dealing $s1 Physical damage and has a chance to Stun for $15753d or Disarm for $15752d.", description="Scaglia un boomerang magico contro il nemico bersaglio, infliggendo $s1 danni fisici e con una probabilità di stordirlo per $15753d o disarmarlo per $15752d." },
  [15743] = { en="Inflicts $s1 Fire damage to all enemies in a selected area, knocking them back and stunning them for $d.", description="Infligge $s1 danni da fuoco a tutti i nemici nell'area selezionata, respingendoli e stordendoli per $d." },
  [16035] = { en="Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by $m1%.", description="Aumenta del $m1% i danni inflitti da Dardo Fulminante, Catena di Fulmini e Folgore della Terra." },
  [16038] = { en="Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by $m1%.", description="Aumenta del $m1% i danni inflitti dai tuoi totem di fuoco e dagli incantesimi Folgore del Fuoco, Nova di Fuoco e Eruzione di Lava." },
  [16039] = { en="Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by $m1%.", description="Riduce del $m1% il costo in mana di Folgore, Dardo Fulminante, Eruzione di Lava e Catena di Fulmini." },
  [16040] = { en="Reduces the cooldown of your Shock spells by ${$m1/-1000}.1 sec.", description="Riduce di ${$m1/-1000}.1 s il tempo di recupero degli incantesimi Folgore." },
  [16043] = { en="Increases the health of your Stoneclaw Totem by $m1% and the radius of your Earthbind Totem by $m2%.", description="Aumenta del $m1% la salute del tuo Totem della Pietra e del $m2% il raggio del tuo Totem Vincolaterra." },
  [16086] = { en="Increases the damage done by your Fire Nova spell by $m1% and reduces its cooldown by ${$m2/-1000} sec.", description="Aumenta del $m1% i danni inflitti da Nova di Fuoco e ne riduce il tempo di recupero di ${$m2/-1000} s." },
  [16089] = { en="Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by $m1%.", description="Aumenta del $m1% il bonus ai danni da colpo critico dei Totem di Fuoco e Magma e dei tuoi incantesimi di fuoco, gelo e natura." },
  [16120] = { en="Increases the critical strike chance of your Lightning Bolt and Chain Lightning spells by $s1%.", description="Aumenta del $s1% la probabilità di colpo critico di Dardo Fulminante e Catena di Fulmini." },
  [16164] = { en="Gives you a $h% chance to enter a Clearcasting state after casting any Fire, Frost, or Nature damage spell.  The Clearcasting state reduces the mana cost of your next damage spell by $16246s1%.", description="Conferisce una probabilità del $h% di entrare nello stato di Lancio Gratuito dopo aver lanciato un incantesimo di danno da fuoco, gelo o natura. Lo stato di Lancio Gratuito riduce del $16246s1% il costo in mana del tuo prossimo incantesimo che infligge danni." },
  [16173] = { en="Reduces the Mana cost of your totems and any spells that summon or move them by $m1%.", description="Riduce del $m1% il costo in mana dei tuoi totem e degli incantesimi che li evocano o spostano." },
  [16176] = { en="Increases your target's armor value by $m1% for $16177d after getting a critical effect from one of your healing spells.", description="Dopo aver ottenuto un effetto critico con un incantesimo di cura, aumenta del $m1% l'armatura del bersaglio per $16177d." },
}
for id, value in pairs(entries) do ns.data.spellDescriptionOverrides[id] = value end
